import{c as n,Q as a,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const p="/assets/Tensor%E5%8E%9F%E5%9C%B0%E6%93%8D%E4%BD%9C%E5%AE%9E%E7%8E%B0%E5%8E%9F%E7%90%86.sIdk1qwk.png",h=JSON.parse('{"title":"如何使用Tensor原地操作提升算子性能","description":"","frontmatter":{},"headers":[{"level":1,"title":"如何使用Tensor原地操作提升算子性能","slug":"如何使用tensor原地操作提升算子性能"},{"level":2,"title":"Tensor原地操作的优势","slug":"tensor原地操作的优势"},{"level":2,"title":"保留EnQue和DeQue的原因","slug":"保留enque和deque的原因"},{"level":2,"title":"适用场景","slug":"适用场景"},{"level":2,"title":"使用方法","slug":"使用方法"},{"level":2,"title":"示例代码","slug":"示例代码"}],"relativePath":"guide/编程指南/附录/常用操作/如何使用Tensor原地操作提升算子性能.md","filePath":"guide/编程指南/附录/常用操作/如何使用Tensor原地操作提升算子性能.md"}'),o={name:"guide/编程指南/附录/常用操作/如何使用Tensor原地操作提升算子性能.md"};function i(c,s,t,r,u,_){return a(),e("div",null,[...s[0]||(s[0]=[l('<h1 id="如何使用tensor原地操作提升算子性能" tabindex="-1">如何使用Tensor原地操作提升算子性能 <a class="header-anchor" href="#如何使用tensor原地操作提升算子性能" aria-label="Permalink to &quot;如何使用Tensor原地操作提升算子性能&quot;">​</a></h1><p>Tensor原地操作（inplace接口）是一种优化技术，全局申请、保留LocalTensor内存，避免了频繁创建和销毁LocalTensor对象。AllocTensor、FreeTensor、EnQue、DeQue接口不产生新的LocalTensor，而是在该全局LocalTensor上反复申请、释放、入队、出队。其实现原理如下图所示：</p><p><strong>图 1</strong> Tensor原地操作实现原理<br><img src="'+p+`" alt="" title="Tensor原地操作实现原理"></p><h2 id="tensor原地操作的优势" tabindex="-1">Tensor原地操作的优势 <a class="header-anchor" href="#tensor原地操作的优势" aria-label="Permalink to &quot;Tensor原地操作的优势&quot;">​</a></h2><ul><li><strong>减少栈变换</strong>：相比构造新Tensor的方式，inplace接口减少了LocalTensor的栈变换，允许Tensor被反复使用。</li><li><strong>减少入队/出队操作</strong>：在调用EnQue、DeQue的过程中，TQue对象没有存储该Tensor对应的Buffer地址，实际没有真正入队、出队，减少了反复入队、出队的Scalar指令。</li></ul><h2 id="保留enque和deque的原因" tabindex="-1">保留EnQue和DeQue的原因 <a class="header-anchor" href="#保留enque和deque的原因" aria-label="Permalink to &quot;保留EnQue和DeQue的原因&quot;">​</a></h2><p>既然Tensor原地操作没有执行真正的入队出队操作，为什么还需要保留EnQue和DeQue接口呢？</p><ul><li><strong>编程兼容性</strong>：为了保持编程接口的一致性，inplace接口仍然需要调用EnQue和DeQue，确保代码结构的统一性和可维护性。</li><li><strong>内存同步功能</strong>：EnQue和DeQue操作中实现了内存读写同步功能，确保数据的一致性和正确性，即使没有实际的队列操作，这些同步机制仍然需要保留。</li></ul><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p><strong>适合计算循环次数多的场景</strong>：如<a href="#fig1745165317496">图1</a>所示，inplace接口虽然增加了TQue对象InitBuffer的初始化开销，但显著减少了每次循环中AllocTensor、EnQue、DeQue和FreeTensor内部对LocalTensor和事件的操作次数，特别适合需要多次循环来完成计算的场景。</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><ul><li><strong>配置TQue对象</strong>：在创建TQue对象时，设置深度（depth）为0，启用inplace操作模式。</li><li><strong>调用原地操作接口</strong>：使用inplace接口直接操作LocalTensor。 <ul><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AllocTensor.md" target="_blank" rel="noreferrer">AllocTensor</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>区分non-inplace和inplace接口，详情请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AllocTensor.md" target="_blank" rel="noreferrer">AllocTensor</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>。</li><li>FreeTensor和EnQue不区分non-inplace和inplace接口。</li></ul></li></ul><h2 id="示例代码" tabindex="-1">示例代码 <a class="header-anchor" href="#示例代码" aria-label="Permalink to &quot;示例代码&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ...</span></span>
<span class="line"><span>namespace AscendC {</span></span>
<span class="line"><span>class MyKernel {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    __aicore__ inline MyKernel() {}</span></span>
<span class="line"><span>    __aicore__ inline void Init(__gm__ uint8_t* src0Gm, __gm__ uint8_t* src1Gm, __gm__ uint8_t* dstGm)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        src0Global.SetGlobalBuffer((__gm__ half*)src0Gm);</span></span>
<span class="line"><span>        src1Global.SetGlobalBuffer((__gm__ half*)src1Gm);</span></span>
<span class="line"><span>        dstGlobal.SetGlobalBuffer((__gm__ half*)dstGm);</span></span>
<span class="line"><span>        pipe.InitBuffer(srcQue0, 1, BLOCK_SIZE * sizeof(half));</span></span>
<span class="line"><span>        pipe.InitBuffer(srcQue1, 1, BLOCK_SIZE * sizeof(half));</span></span>
<span class="line"><span>        pipe.InitBuffer(dstQue0, 1, BLOCK_SIZE * sizeof(half));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    __aicore__ inline void Process()</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        for (int i = 0; i &lt; REPTIMES; i++) {</span></span>
<span class="line"><span>            CopyIn(i);</span></span>
<span class="line"><span>            Compute(i);</span></span>
<span class="line"><span>            CopyOut(i);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    __aicore__ inline void CopyIn(int32_t i)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        srcQue0.AllocTensor&lt;half&gt;(src0Local);</span></span>
<span class="line"><span>        srcQue1.AllocTensor&lt;half&gt;(src1Local);</span></span>
<span class="line"><span>        DataCopy(src0Local, src0Global[i*BLOCK_SIZE], BLOCK_SIZE);</span></span>
<span class="line"><span>        DataCopy(src1Local, src1Global[i*BLOCK_SIZE], BLOCK_SIZE);</span></span>
<span class="line"><span>        srcQue0.EnQue(src0Local);</span></span>
<span class="line"><span>        srcQue1.EnQue(src1Local);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    __aicore__ inline void Compute(int32_t i)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        srcQue0.DeQue&lt;half&gt;(src0Local);</span></span>
<span class="line"><span>        srcQue1.DeQue&lt;half&gt;(src1Local);</span></span>
<span class="line"><span>        dstQue0.AllocTensor&lt;half&gt;(dstLocal);</span></span>
<span class="line"><span>        Add(dstLocal, src0Local, src1Local, BLOCK_SIZE);</span></span>
<span class="line"><span>        dstQue0.EnQue&lt;half&gt;(dstLocal);</span></span>
<span class="line"><span>        srcQue0.FreeTensor(src0Local);</span></span>
<span class="line"><span>        srcQue1.FreeTensor(src1Local);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    __aicore__ inline void CopyOut(int32_t i)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        dstQue0.DeQue&lt;half&gt;(dstLocal);</span></span>
<span class="line"><span>        DataCopy(dstGlobal[i*BLOCK_SIZE], dstLocal, BLOCK_SIZE);</span></span>
<span class="line"><span>        dstQue0.FreeTensor(dstLocal);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    TPipe pipe;</span></span>
<span class="line"><span>    TQue&lt;QuePosition::VECIN, 0&gt; srcQue0, srcQue1;</span></span>
<span class="line"><span>    TQue&lt;QuePosition::VECOUT, 0&gt; dstQue0;</span></span>
<span class="line"><span>    GlobalTensor&lt;half&gt; src0Global, src1Global, dstGlobal;</span></span>
<span class="line"><span>    LocalTensor&lt;half&gt; src0Local;</span></span>
<span class="line"><span>    LocalTensor&lt;half&gt; src1Local;</span></span>
<span class="line"><span>    LocalTensor&lt;half&gt; dstLocal;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>} // namespace AscendC</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ...</span></span></code></pre></div>`,14)])])}const g=n(o,[["render",i]]);export{h as __pageData,g as default};
